from __future__ import annotations

import re
from datetime import datetime, timedelta


_MONTH_NAMES = {
    "JAN": 1,
    "FEB": 2,
    "MAR": 3,
    "APR": 4,
    "MAY": 5,
    "JUN": 6,
    "JUL": 7,
    "AUG": 8,
    "SEP": 9,
    "OCT": 10,
    "NOV": 11,
    "DEC": 12,
}

_WEEKDAY_NAMES = {
    "SUN": 0,
    "MON": 1,
    "TUE": 2,
    "WED": 3,
    "THU": 4,
    "FRI": 5,
    "SAT": 6,
}

_DIGITS = re.compile(r"[0-9]+\Z")
_SEARCH_YEARS = 5


def _parse_value(text, low, high, names):
    if names is not None:
        value = names.get(text.upper())
        if value is not None:
            return value
    if _DIGITS.fullmatch(text) is None:
        raise ValueError("invalid cron value: {!r}".format(text))
    value = int(text)
    if not low <= value <= high:
        raise ValueError(
            "cron value {} is outside {}..{}".format(value, low, high)
        )
    return value


def _parse_field(text, low, high, names=None):
    if not text:
        raise ValueError("empty cron field")

    values = set()
    for item in text.split(","):
        if not item:
            raise ValueError("empty cron item")

        if item.count("/") > 1:
            raise ValueError("malformed cron item: {!r}".format(item))

        has_step = "/" in item
        if has_step:
            base, step_text = item.split("/")
            if _DIGITS.fullmatch(step_text) is None:
                raise ValueError("invalid cron step: {!r}".format(step_text))
            step = int(step_text)
            if step == 0:
                raise ValueError("cron step must be positive")
        else:
            base = item
            step = 1

        if base == "*":
            start, end = low, high
        elif "-" in base:
            if base.count("-") != 1:
                raise ValueError("malformed cron range: {!r}".format(base))
            start_text, end_text = base.split("-")
            start = _parse_value(start_text, low, high, names)
            end = _parse_value(end_text, low, high, names)
            if start > end:
                raise ValueError("descending cron range: {!r}".format(base))
        else:
            start = end = _parse_value(base, low, high, names)
            # ``N/S`` runs from N through the end of the field's range.
            if has_step:
                end = high

        values.update(range(start, end + 1, step))

    return values


def _parse_expression(expression):
    fields = expression.split()
    if len(fields) != 5:
        raise ValueError(
            "cron expression must have five fields, got {}".format(len(fields))
        )

    minute_text, hour_text, dom_text, month_text, dow_text = fields
    minutes = _parse_field(minute_text, 0, 59)
    hours = _parse_field(hour_text, 0, 23)
    days = _parse_field(dom_text, 1, 31)
    months = _parse_field(month_text, 1, 12, _MONTH_NAMES)
    weekdays = {
        0 if value == 7 else value
        for value in _parse_field(dow_text, 0, 7, _WEEKDAY_NAMES)
    }

    # Vixie cron only treats a literally bare ``*`` as unrestricted.
    return (
        minutes,
        hours,
        days,
        months,
        weekdays,
        dom_text != "*",
        dow_text != "*",
    )


def _day_matches(day, days, weekdays, dom_restricted, dow_restricted):
    dom_match = day.day in days
    # Python's Monday is 0; cron's Sunday is 0 and Monday is 1.
    dow_match = (day.weekday() + 1) % 7 in weekdays
    if dom_restricted and dow_restricted:
        return dom_match or dow_match
    return dom_match and dow_match


def _five_years_after(value):
    target_year = value.year + _SEARCH_YEARS
    if target_year > datetime.max.year:
        return datetime.max
    try:
        return value.replace(year=target_year)
    except ValueError:
        # 29 February in a non-leap target year.
        return value.replace(year=target_year, day=28)


def next_run(expression: str, after: datetime) -> datetime:
    """The first time after ``after`` that ``expression`` fires."""
    (
        minutes,
        hours,
        days,
        months,
        weekdays,
        dom_restricted,
        dow_restricted,
    ) = _parse_expression(expression)

    # The first whole minute strictly after ``after``.
    try:
        start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    except OverflowError:
        raise ValueError(
            "no matching time within five years for {!r}".format(expression)
        ) from None

    limit = _five_years_after(start)
    start_date = start.date()
    last_date = limit.date()
    hours_sorted = sorted(hours)
    minutes_sorted = sorted(minutes)
    one_day = timedelta(days=1)
    day = start_date

    while day <= last_date:
        if day.month in months and _day_matches(
            day, days, weekdays, dom_restricted, dow_restricted
        ):
            for hour in hours_sorted:
                if day == start_date and hour < start.hour:
                    continue
                first_minute = (
                    start.minute
                    if day == start_date and hour == start.hour
                    else 0
                )
                for minute in minutes_sorted:
                    if minute < first_minute:
                        continue
                    candidate = datetime(
                        day.year, day.month, day.day, hour, minute
                    )
                    if candidate > limit:
                        raise ValueError(
                            "no matching time within five years for "
                            "{!r}".format(expression)
                        )
                    return candidate
        day += one_day

    raise ValueError(
        "no matching time within five years for {!r}".format(expression)
    )
